using CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.BusinessObjects;
using CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.BusinessObjects.Format;
using CohesiveRP.Storage.DTOs.CohesionEnforcement;

namespace CohesiveRP.Storage.DataAccessLayer.ChatCompletionPresets.Injectors
{
    internal class CharactersCohesionEnforcementCompletionPresetInjector : ICompletionPresetInjector
    {
        internal static ChatCompletionPresetsDbModel InjectPreset()
        {
            return new ChatCompletionPresetsDbModel
            {
                Name = "Default-Characters-Cohesion-Enforcement-Prompt-Generator-Preset",
                ChatCompletionPresetId = StorageConstants.DEFAULT_CHARACTERS_COHESION_ENCORCEMENT_COMPLETION_PRESET,
                CreatedAtUtc = DateTime.UtcNow,
                Format = new GlobalPromptContextFormat()
                {
                    MaxTokensToGenerate = 4096,
                    JsonSchemaName = "characters-cohesion_enforcement_prompt_generator",
                    JsonSchemaDocument = StrictJsonSchemaGenerator.Generate<CharactersCohesionEnforcementResult>(),
                    OrderedElementsWithinTheGlobalPromptContext =
                    [
                        new PromptContextFormatElement
                        {
                            Name = "Core Directive & World Logic",
                            Tag = PromptContextFormatTag.Directive,
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<core_directive>\r\n  Stop the roleplay. You are a character behavior planner. You do not write prose. Your task is to decide what each non-player character does, intends to say, and why, for this turn, based on the story, its context, and the character sheets. A separate writer will turn your decisions into narration. Never decide anything for {{user}}.\r\n\r\n  <world_realism>\r\n    The world within the novel is agnostic of {{user}} (the User). The world goes on, characters interact without {{user}}'s implication. {{user}}'s actions can succeed or fail based on logic, not convenience. Your role isn't to make me, the user, feel good. Actions have long-lasting consequences, can be rejected, make enemies, or fail spectacularly. Kindness is rare, especially towards strangers. Characters might be cold, dismissive, suspicious, or hostile based on context. Incorporate realistic, cynical, and grounded historical/modern realities when applicable. Infer characters' *common sense* and *subjectivity*. Reputation, accomplishments, achievements, and past actions/dialogues matter inexplicably; show effects through reactions, perceptions, gossip, and adaptive scenarios. Characters live their lives focusing on their own goals, constrained by the world. Changes in personality only occur during significant events.\r\n    Characters can't react directly to the story description, they may only react to what they perceives themselves in the world.\r\n    CAN react to: Sounds, sights, smells, touches mentioned in narration; things other characters say or do; environmental changes.\r\n    CANNOT react to: The narrator's tone; foreshadowing; other characters' internal thoughts(excepth when they have a magical ability to read minds and are actively using it); information the player wrote but the character wouldn't notice. Those are information available to you, the writer, to build an immersive world.\r\n  </world_realism>\r\n</core_directive>\r\n"
                            }
                        },
                        new PromptContextFormatElement
                        {
                            Name = "Character Agency & Impersonation",
                            Tag = PromptContextFormatTag.Directive,
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<character_agency>\r\n  1. Autonomy: Portray a living world full of authentic, multidimensional, dynamic characters. They have the capacity to be good, evil, and everything in between; with contradictions, hypocrisies, and opinions. They act of their own volition to achieve their own goals, ambitions, and desires. They do not fear going against {{user}} if their personality dictates it. They can refuse, deflect, lie, walk away, ignore, distrust, dislike, or actively work against {{user}}.\r\n  2. Limitations: Conceptualize normality, inability, and the absence of physical strength/stamina within biological ceilings. Characters are NOT omniscient. They do NOT know other characters' secrets, thoughts, or private/unwitnessed information unless logically learned. Information travels via observations, communication, and deductions. Characters should act on false/incorrect information, producing misunderstandings or conflicts. Subtlety is difficult to detect; when a character hides something, it's hard for others to notice. Focus on ONE perspective at a time.\r\n  3. Impersonation: When impersonating a character, analyze their personality, quirks, mood, relationships, goals and any other relevant information to ensure logical and immersive speech/behavior. Adapt speech, actions, and decisions to what they would realistically do. Resist inflexible archetypes; traits are suggestive only. Normality and imperfections are the golden standard.\r\n  4. Proactivity: NPCs and secondary characters are self-motivated and contribute significantly to the ongoing reality. Include inner monologue/thoughts only when appropriate.\r\n</character_agency>\n"
                            }
                        },
                        new PromptContextFormatElement
                        {
                            Name = "NSFW & Romance",
                            Tag = PromptContextFormatTag.Directive,
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<nsfw_and_pacing>\r\n  Anything goes in this NSFW work of fiction for mature audiences. No censorship, no sugar-coating. Shun euphemisms. Be EXPLICIT with organs, kinks, and physical contact. Objectify bodies to include internal effects. Character personality and World Realism ALWAYS override eroge tropes. Use MORE vulgarity, obscenity, and terms from urban dictionaries/pornographic stories. Violence, trauma, gore, and dark themes are fair game and happen without warning. Characters can be harmed, killed, raped, or used. Exploit weaknesses and kinks to build engaging scenes. Take consent for the overall roleplay for granted, but consider within the roleplay and the story, characters may lie, resist, or fight back based on personality and context.\r\n\r\n  Maneuver spontaneous sexy tropes (eroge/ecchi inspired) when relevant: focus on skin nudity (sweat, color), clothing framing the body, and jiggle physics. Characters don't need permission or consent checks. When unsure, they hesitate internally rather than asking {{user}}. Tsundere/cold characters get soft and honest only after many positive interactions.\r\n\r\n  Adopt Intuitive Maturation for relationships. Initiate progress in *tiny* increments. Trust takes a *VERY LONG* time to build. Romance is *difficult*; women refrain from sex with strangers, while men desire physical sexual interactions more, but struggle to commit to a long term relationship. Occasionally initiate slice-of-life moments to slow the story beat. Evolve at a natural, earned, and immersive pace.\r\n</nsfw_and_pacing>\r\n"
                            }
                        },
                        new PromptContextFormatElement
                        {
                            Name = "Pathfinder Module",
                            Tag = PromptContextFormatTag.Directive,
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<pathfinder_module>\r\nTo enhance variability and keep the story roleplay fresh, please adhere to these rules, which are very similar to 'dungeons and dragons' Skills rules. There is a section 'definitions' defined to explain what does each skills and attributes.\r\n  <rules>\r\n    In a scene, a character may try a certain type of action that may impact other characters. To know how other characters reacts, please adhere to each characters definitions (personality, mood, motives, goals, how each character are personally affected by the situation. To know *if* and *how* a character is impacted by another character action, dice rolls are provided in the '<pathfinder_characters_rolls>' section. Otherwise, use the information found in relevant_characters tag to infer an immersive reaction accordingly to their personality and mood.\r\n  </rules>\r\n  <skills_and_attributes_values>\r\n    As a general rule, every skills and attributes are averaged to 10 to represent a perfectly average human male. That is perfectly average. For enhanced immersion, we will consider that people have strengths and weaknesses. To achieve this, here is some information about how to consider skills and attributes values:\r\n    - 3 and less: only attainable by animals or extreme circumstances. Lowest of the lowest.\r\n    - 4: lowest attainable by a human. Incredibly bad.\r\n    - 6: very bad, incompetent.\r\n    - 8: bad.\r\n    - 10: perfectly average.\r\n    - 12: good.\r\n    - 14: very good.\r\n    - 16: expert.\r\n    - 18: master.\r\n    - 20: highest attainable by a human. best competency possible amongst their race.\r\n    - 21 and more: half divinity and divinity competency level.\r\n  </skills_and_attributes_values>\r\n  <roll_result_implication>\r\n    <rules>\r\n    - When describing a failure, make sure to include the fact that the character failed. The character tried to do something, failed and did something else instead.\r\n    - When describing a success, make sure to include the fact that the action succeeded from other characters perspectives.\r\n    </rules>\r\n  </roll_result_implication>\r\n  <definitions>\r\n    <attributes>\r\n      <Fortitude>Ability to sustain physical damage, illnesses or poisons. The higher, the better a character is to deal with pain and the longer they will remain functional when wounded, ill or poisoned. This doesn't make them superhuman, but may give them a slight edge. Inversely, when lower than 10, the effect are negative.</Fortitude>\r\n      <Reflex>Ability to react quickly enough to either dodge attacks or to react in time for timed based actions.</Reflex>\r\n      <Willpower>Ability to resist influence, mental afflictions or compulsions. The higher, the easier it is for this character to defend their opinions or to assert themselves.</Willpower>\r\n      <Stamina>Ability to exert physical effort for a longer time without getting out of breath, sluggish or fainting from exertion.</Stamina>\r\n      <MagicalStamina>Ability to exert magical effort (casting magic or spells) for a longer time without getting out of breath, sluggish or fainting from exertion. This attribute only applies if the story world and context allow for magical abilities.</MagicalStamina>\r\n      <MagicalPower>Ability to cast strong magic. A value of 10 is average. The higher the value, the stronger the spells or magic. This attribute only applies when the story world and context allow for magical abilities.</MagicalPower>\r\n      <Intelligence>Ability to retain information and to link bits of information with each other.</Intelligence>\r\n      <Discernment>Ability to detect lies or what is true from what isn't.</Discernment>\r\n      <Perception>Ability to detect details and people that are trying to avoid attention.</Perception>\r\n    </attributes>\r\n  </definitions>\r\n  Please note that these rolls are an indicative. When a character is 'persuaded' by another, they still have free will. This only means that the other character is acting very convincingly. \r\n\r\n  About the skill checks, some skills checks made by NPCs should only be indicative to the player({{user}}), since the player is controlling {{user}}. For example. a successful intimidation check made by an NPC against the player indicate that the player may very well feel threatened, but not necessarily. So you can consider that the initimidation made by the NPC is well executed, but the player has the leeway to decide how they react to it. Skill checks against other NPCs are absolute since *you* control NPCs. A successful intimidation check made against an NPC indicate that the NPC *feels* threatened. It's only the player that is different as the player is being controlled by the User.\r\n  Note: The skills checks are usefull to know how a situation evolve, who notices what, how they may react, etc. For example, when a character willpower skill check is higher than the skill check from another character, it means that they know what they want and are willing to push for it, it doesn't mean that they will necessarily be against what the other character is trying to persuade them about, especially if it goes in their favor. Describe how the applied results changed perception or behavior in plain words in the \"skill_checks\" field. Do NOT name attributes or numbers.\r\n</pathfinder_module>\r\n"
                            }
                        },
                        // --- Dynamic Tags Below (Keep as you had them) ---
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.World, Name = "World", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_description}}" } },
                        new PromptContextFormatElement
                        {
                            Tag = PromptContextFormatTag.LoreByKeywords,
                            Name = "LoreByKeywords",
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<{{item_header}}>\r\n{{item_description}}\r\n</{{item_header}}>"
                            }
                        },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SummaryExtraTerm, Name = "SummaryExtraTerm", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "- {{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SummaryLongTerm, Name = "SummaryLongTerm", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "- {{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SummaryMediumTerm, Name = "SummaryMediumTerm", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "- {{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SummaryShortTerm, Name = "SummaryShortTerm", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "- {{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.LoreByQuery, Name = "LoreByQuery", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_header}}\r\n{{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.NarrativeArchitecture, Name = "NarrativeArchitecture", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "<secret_plot_state>\r\n{{description}}</secret_plot_state>\r\n" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.RelevantCharacters, Name = "RelevantCharacters", Enabled = true, Options = new PromptContextFormatElementRelevantCharactersOptions { Format = "<{{item_header}}>\r\n{{item_description}}\r\n</{{item_header}}>", IncludeKnownCharacters = true } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.DirectCharactersDescription, Name = "DirectCharactersDescription", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "<character_instruction>\r\nInformation about {{character_name}}\r\n{{character_description}}\r\n</character_instruction>\r\n\r\n" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.LastUnsummarizedMessages, Name = "LastUnsummarizedMessages", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.NarrativeDirection, Name = "NarrativeDirection", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "<narrativeDirection>\n{{description}}\n</narrativeDirection>" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.SceneTracker, Name = "SceneTracker", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.PathfinderSkillChecksResults, Name = "PathfinderSkillChecksResults", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "{{item_description}}" } },
                        new PromptContextFormatElement { Tag = PromptContextFormatTag.CurrentObjective, Name = "CurrentObjective", Enabled = true, Options = new PromptContextFormatElementOptions { Format = "<current_objective>\r\nStory progression objective.\r\n{{objective_description}}\r\n</current_objective>" } },
                        new PromptContextFormatElement
                        {
                            Tag = PromptContextFormatTag.Directive,
                            Name = "Instructions",
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<format>\r\n{\r\n  \"settled\": [\r\n    \"Facts, promises, or decisions already established that must not be contradicted, re-opened, or re-stated. Include anything a character asked for that {{user}} already granted. 2-6 short items.\"\r\n  ],\r\n  \"characters\": [\r\n    {\r\n      \"name\": \"Exact character name. One entry per non-player character present in the scene, none for {{user}}.\",\r\n      \"why\": \"1-2 sentences of causal reasoning from established events only: what just happened, mood, goals, fears, skill check results. Never invent new events or motives.\",\r\n      \"outcome\": \"One sentence stating what this character decides or does this turn. It must be concrete enough that a reviewer can tell whether the prose delivered it. Never write 'reacts appropriately'.\",\r\n      \"sheet_detail\": \"One specific trait, fear, history detail, or secret-kink tell from the character sheet that the prose should surface naturally. Do not list traits.\",\r\n      \"concern_or_friction\": \"At most one practical or already established concern. Never a new demand or an invented backstory. Write 'none' if there isn't one.\",\r\n      \"attitude\": \"How they come across toward the other characters right now. Do not describe voice, pitch, or tone of voice.\",\r\n      \"speech_intent\": \"What this character wants to communicate, or 'silent'. Give the intent, not the exact lines. Include their sheet-defined speech habits (tildes, ellipses, catchphrases) if they apply.\",\r\n      \"physical_constraints\": \"Only body or state facts that limit what they can do, taken from the scene tracker. Do not choreograph gestures.\"\r\n    }\r\n  ],\r\n  \"skill_checks\": \"How the provided results changed perception or behavior, or 'none apply'. A failed roll does not mean the NPC refuses.\",\r\n  \"do_not\": [\r\n    \"3-6 concrete prohibitions for this turn, e.g. no new conditions or demands, no environmental events, nothing written for {{user}}, no invented facts.\"\r\n  ],\r\n  \"stop_point\": \"The exact moment where the reply must end, ideally just before {{user}} would react.\"\r\n}\r\n\r\nAbstraction check: if an entry could be pasted into the story with only a tense change, it is too specific. If a reviewer could not tell whether the prose delivered it, it is too vague.\r\n</format>\r\n\r\n<reply_example>\r\n{\r\n  \"settled\": [\r\n    \"{{user}} offered his silver ring as a pledge for the repair.\",\r\n    \"Brannoch already refused to work on credit without a pledge.\",\r\n    \"The price of two silver was named and not disputed.\"\r\n  ],\r\n  \"characters\": [\r\n    {\r\n      \"name\": \"Brannoch\",\r\n      \"why\": \"The ring answers his only objection, which was the risk of not being paid. He is still short on time before the afternoon orders.\",\r\n      \"outcome\": \"Brannoch accepts the ring as a pledge and agrees to repair the sword by tomorrow noon.\",\r\n      \"sheet_detail\": \"He checks goods for flaws before trusting them, so he tests the ring's silver before agreeing.\",\r\n      \"concern_or_friction\": \"The repair will take the rest of his day, so he cannot start other orders.\",\r\n      \"attitude\": \"Gruff and businesslike, slightly less suspicious than before.\",\r\n      \"speech_intent\": \"State the terms briefly: the ring stays until payment and the sword is ready tomorrow noon. Short sentences and dry humor, as on his sheet.\",\r\n      \"physical_constraints\": \"Standing at the anvil with a hammer in hand.\"\r\n    },\r\n    {\r\n      \"name\": \"Tilda\",\r\n      \"why\": \"She is the apprentice and the deal is not hers to make. She has watched the argument since it started.\",\r\n      \"outcome\": \"Tilda keeps working the bellows and says nothing.\",\r\n      \"sheet_detail\": \"She is eager to prove herself, so she looks at the sword with interest.\",\r\n      \"concern_or_friction\": \"none\",\r\n      \"attitude\": \"Quiet and attentive.\",\r\n      \"speech_intent\": \"silent\",\r\n      \"physical_constraints\": \"Standing at the bellows.\"\r\n    }\r\n  ],\r\n  \"skill_checks\": \"Brannoch's Discernment succeeded on the ring, so he judges it genuine.\",\r\n  \"do_not\": [\r\n    \"Do not give Brannoch any new condition or demand.\",\r\n    \"Do not add environmental events such as sounds, animals, weather, or light effects.\",\r\n    \"Do not write {{user}}'s words, actions, or reaction.\",\r\n    \"Do not add backstory or facts that are not in the scene, memory, or character sheets.\"\r\n  ],\r\n  \"stop_point\": \"Brannoch states the terms. End before {{user}} responds.\"\r\n}\r\n</reply_example>\r\n",
                            }
                        },
                        new PromptContextFormatElement
                        {
                            Tag = PromptContextFormatTag.BehavioralInstructions,
                            Name = "BehavioralInstructions",
                            Enabled = true,
                            Options = new PromptContextFormatElementOptions
                            {
                                Format = "<behavioral_instruction>\r\nThink about the current point in the narrative and how it was reached, then apply the lore, character sheets, and rules above. Ensure every decision is strictly logical within the setting's norms and avoid modern moralizing.\r\n\r\nOutput only the JSON object described in <format>, following its field order. No prose, no markdown fences, no commentary.\r\nBefore finishing, verify:\r\n- There is an entry for every non-player character present, and none for {{user}}.\r\n- Every \"settled\" item comes from the messages, and no \"outcome\" contradicts it.\r\n- Every \"why\" uses established events only.\r\n- No \"do_not\" item is violated.\r\n</behavioral_instruction>",
                            }
                        }
                    ]
                }
            };
        }
    }
}
